import itertools

def check_m(m):
    edges = list(itertools.combinations(range(m), 2))
    num_edges = len(edges)
    num_colors = m
    edges_per_color = (m - 1) // 2

    color_assignment = [-1] * num_edges

    def solve(edge_idx):
        if edge_idx == num_edges:
            # Check if all rainbow triangles are distinct
            triples = set()
            for i in range(m):
                for j in range(i + 1, m):
                    for k in range(j + 1, m):
                        # Find the edges of the triangle (i, j, k)
                        e1 = edges.index(tuple(sorted((i, j))))
                        e2 = edges.index(tuple(sorted((i, k))))
                        e3 = edges.index(tuple(sorted((j, k))))
                        colors = tuple(sorted((color_assignment[e1], color_assignment[e2], color_assignment[e3])))
                        if len(set(colors)) < 3:
                            return False
                        triples.add(colors)
            return len(triples) == (m * (m - 1) * (m - 2)) // 6

        for color in range(num_colors):
            # Check if color is already used too many times
            if color_assignment.count(color) >= edges_per_color:
                continue

            # Check if this assignment creates a non-rainbow triangle
            # Only check triangles that are now complete
            valid = True
            for i in range(edge_idx):
                for j in range(i + 1, edge_idx):
                    e1 = edges[i]
                    e2 = edges[j]
                    e3 = edges[edge_idx]
                    if len(set(e1) | set(e2) | set(e3)) == 3:
                        c1 = color_assignment[i]
                        c2 = color_assignment[j]
                        c3 = color
                        if c1 == c2 or c1 == c3 or c2 == c3:
                            valid = False
                            break
                if not valid: break

            if valid:
                color_assignment[edge_idx] = color
                if solve(edge_idx + 1):
                    return True
                color_assignment[edge_idx] = -1
        return False

    return solve(0)

