    num_colors = m

    color_assignment = [-1] * num_edges

    def solve(edge_idx):
        if edge_idx == num_edges:
            triples = set()
            for i in range(m):
                for j in range(i + 1, m):
                    for k in range(j + 1, m):
                        e1 = edges.index(tuple(sorted((i, j))))
                        e2 = edges.index(tuple(sorted((i, k))))
                        e3 = edges.index(tuple(sorted((j, k))))
                        colors = tuple(sorted((color_assignment[e1], color_assignment[e2], color_assignment[e3])))
                        if len(set(colors)) < 3:
                            return False
                        triples.add(colors)
            return len(triples) == (m * (m - 1) * (m - 2)) // 6

        for color in range(num_colors):
            # Each vertex must have distinct colors for its edges
            # Edge is (u, v)
            u, v = edges[edge_idx]

            # Check if any other edge from u or v already has this color
            possible = True
            for i in range(edge_idx):
                e_i = edges[i]
                if (u in e_i or v in e_i) and color_assignment[i] == color:
                    possible = False
                    break
            if not possible:
                continue

            # Check if this creates a non-rainbow triangle
            for i in range(edge_idx):
                for j in range(i + 1, edge_idx):
                    e_i = edges[i]
                    e_j = edges[j]
                    if len(set(e_i) | set(e_j) | set(edges[edge_idx])) == 3:
                        c_i = color_assignment[i]
                        c_j = color_assignment[j]
                        if c_i == c_j or c_i == color or c_j == color:
                            possible = False
                            break
                if not possible: break

            if possible:
                color_assignment[edge_idx] = color
                if solve(edge_idx + 1):
                    return True
                color_assignment[edge_idx] = -1
        return False

    return solve(0)

