def solve_m(m):
    edges = list(itertools.combinations(range(m), 2))
    num_edges = len(edges)

    color_assignment = [-1] * num_edges

    def solve(edge_idx):
        if edge_idx == num_edges:
            return True

        u, v = edges[edge_idx]
        # Color c cannot be u or v
        # Also c cannot be used for any other edge incident to u or v
        # Also c cannot create a non-rainbow triangle

        for c in range(m):
            if c == u or c == v:
                continue

            # Proper coloring check
            possible = True
            for i in range(edge_idx):
                e_i = edges[i]
                if (u in e_i or v in e_i) and color_assignment[i] == c:
                    possible = False
                    break
            if not possible: continue

            # Rainbow triangle check
            for i in range(edge_idx):
                for j in range(i + 1, edge_idx):
                    e_i = edges[i]
                    e_j = edges[j]
                    if len(set(e_i) | set(e_j) | set(edges[edge_idx])) == 3:
                        c_i = color_assignment[i]
                        c_j = color_assignment[j]
                        if c_i == c_j or c_i == c or c_j == c:
                            possible = False
                            break
                if not possible: break

            if possible:
                color_assignment[edge_idx] = c
                if solve(edge_idx + 1):
                    return True
                color_assignment[edge_idx] = -1
        return False

    return solve(0)

